public class A41 {
 public Integer seq=0;
 public String results(List<Messaging.SendEmailResult> xs) {
  if(xs==null) return 'null';
  List<String> out=new List<String>();
  for(Messaging.SendEmailResult x:xs) {
   if(x==null){out.add('null-result');continue;}
   List<String> errors=new List<String>();
   for(Messaging.SendEmailError e:x.getErrors()) errors.add(String.valueOf(e.getStatusCode())+'|'+e.getMessage()+'|'+String.valueOf(e.getFields())+'|target-null='+String.valueOf(e.getTargetObjectId()==null));
   out.add(String.valueOf(x.isSuccess())+'|'+String.join(errors,';'));
  }
  return xs.size()+':'+String.join(out,'/');
 }
 public EmailTemplate template(String variant) {
  String developerName='A41'+variant+'20261005';
  return [SELECT Id FROM EmailTemplate WHERE DeveloperName=:developerName AND Folder.DeveloperName='A41MessagingOracle20261005'];
 }
}

Declarations.A41InboundOracle20261005:
public class A41InboundOracle20261005 implements Messaging.InboundEmailHandler {
 public Messaging.InboundEmailResult handleInboundEmail(Messaging.InboundEmail mail, Messaging.InboundEnvelope envelope) {
  Messaging.InboundEmailResult result=new Messaging.InboundEmailResult();
  result.success=mail!=null && envelope!=null;
  result.message=mail==null?'no-mail':(envelope==null?'no-envelope':String.valueOf(mail.subject)+'|'+String.valueOf(envelope.toAddress));
  return result;
 }
}

